+        #region Connect
+
+        public override bool Connect()
+        {
+            try
+            {
+                if (_initTask != null && !_initTask.IsCompleted)
+                {
+                    // SSH connection will be triggered when xterm.js sends "ready" message
+                    _initTask.ContinueWith(t =>
+                    {
