+            }
+        }
+
+        private async Task ConnectSshAsync()
+        {
+            try
+            {
+                var info = InterfaceControl.Info;
+                string hostname = info.Hostname;
+                int port = info.Port;
+                string username = info.Username;
+                string password = info.Password;
