+                if (!_sshClient.IsConnected)
+                {
+                    PostOutputToTerminal("\r\n\x1b[31mSSH connection failed.\x1b[0m\r\n");
+                    Event_ErrorOccured(this, "SSH connection failed", null);
+                    return;
+                }
