+                switch (type)
+                {
+                    case "ready":
+                        // xterm.js is ready — start SSH connection
+                        _ = ConnectSshAsync();
+                        break;
+
+                    case "input":
+                        string inputData = root.GetProperty("data").GetString();
+                        WriteToShell(inputData);
+                        break;
+
+                    case "resize":
+                        uint cols = root.GetProperty("cols").GetUInt32();
+                        uint rows = root.GetProperty("rows").GetUInt32();
